@startuml

class User {
  + id : int
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner {
  + linkedinAccount : string
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + id : int
  + orderDateAndTime : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder extends Order {
  + entertainmentType : string
  + duration : time
}

class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Minutes : double
}

class PizzaRestaurantEntertainer {
  + pizzaRestaurant : PizzaRestaurant
  + entertainer : Entertainer
  + availability : List<Day>
}

enum Day {
  Monday
  Tuesday
  Wednesday
  Thursday
  Friday
  Saturday
  Sunday
}

User "1" -- "0..*" BusinessOwner : is
BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
User "1" -- "*" Order : makes
Order "1" -- "0..1" EntertainmentOrder : is
Entertainer "1" -- "*" EntertainmentOrder : fulfills

@enduml

